SYSTEMS_HTML = '<!doctype html>\n<html lang="en">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width, initial-scale=1">\n<title>Personal CIC // Systems</title>\n<style>\n:root {\n  color-scheme: dark;\n  --bg: #080c10;\n  --panel: #0f151b;\n  --panel2: #121b22;\n  --line: #25323d;\n  --text: #e7edf2;\n  --muted: #8da0af;\n  --good: #74d99f;\n  --warn: #e8c56d;\n  --bad: #ef7e7e;\n  --unknown: #9aa7b2;\n  --accent: #79b8ff;\n}\n* { box-sizing: border-box; }\nbody {\n  margin: 0;\n  background: var(--bg);\n  color: var(--text);\n  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;\n}\nheader {\n  position: sticky;\n  top: 0;\n  z-index: 10;\n  background: rgba(8,12,16,.96);\n  border-bottom: 1px solid var(--line);\n  backdrop-filter: blur(10px);\n}\n.brand {\n  display: flex;\n  align-items: baseline;\n  gap: 14px;\n  padding: 16px 20px 10px;\n}\n.brand h1 { margin: 0; font-size: 18px; letter-spacing: .12em; }\n.readonly {\n  color: var(--accent);\n  border: 1px solid #2d5f8a;\n  border-radius: 999px;\n  padding: 2px 8px;\n  font-size: 10px;\n  letter-spacing: .08em;\n}\nnav {\n  display: flex;\n  gap: 8px;\n  padding: 0 20px 12px;\n  overflow-x: auto;\n}\nnav span, nav a {\n  color: var(--muted);\n  border: 1px solid var(--line);\n  padding: 6px 9px;\n  border-radius: 4px;\n  white-space: nowrap;\n  font-size: 11px;\n}\nnav a { text-decoration: none; }\nnav .active { color: var(--text); border-color: #466174; background: #111b23; }\nnav .future { opacity: .45; }\n.status-strip {\n  display: grid;\n  grid-template-columns: repeat(4, minmax(0, 1fr));\n  gap: 8px;\n  padding: 12px 20px 0;\n}\n.status {\n  background: var(--panel);\n  border: 1px solid var(--line);\n  border-radius: 6px;\n  padding: 10px 12px;\n}\n.label { color: var(--muted); font-size: 10px; letter-spacing: .1em; }\n.value { font-size: 14px; margin-top: 4px; }\n.nominal, .current, .connected { color: var(--good); }\n.warning, .degraded { color: var(--warn); }\n.critical, .unavailable, .disconnected { color: var(--bad); }\n.unknown { color: var(--unknown); }\nmain { padding: 14px 20px 28px; }\n.grid {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  gap: 12px;\n}\n.card {\n  border: 1px solid var(--line);\n  background: var(--panel);\n  border-radius: 8px;\n  overflow: hidden;\n}\n.card h2 {\n  margin: 0;\n  padding: 12px 14px;\n  font-size: 12px;\n  letter-spacing: .08em;\n  border-bottom: 1px solid var(--line);\n  background: var(--panel2);\n}\n.metrics {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n}\n.metric {\n  min-height: 72px;\n  padding: 12px 14px;\n  border-right: 1px solid var(--line);\n  border-bottom: 1px solid var(--line);\n}\n.metric:nth-child(even) { border-right: 0; }\n.metric .v {\n  display: block;\n  margin-top: 5px;\n  font-size: 17px;\n  overflow-wrap: anywhere;\n}\n.metric .sub {\n  color: var(--muted);\n  display: block;\n  margin-top: 4px;\n  font-size: 10px;\n  line-height: 1.45;\n}\n.foot {\n  color: var(--muted);\n  padding: 12px 20px 24px;\n  font-size: 10px;\n}\n.reason {\n  padding: 10px 14px;\n  border-top: 1px solid var(--line);\n  color: var(--warn);\n  font-size: 11px;\n}\n@media (max-width: 760px) {\n  .status-strip { grid-template-columns: repeat(2, minmax(0, 1fr)); }\n  .grid { grid-template-columns: 1fr; }\n}\n</style>\n</head>\n<body>\n<header>\n  <div class="brand">\n    <h1>PERSONAL CIC // SYSTEMS</h1>\n    <span class="readonly">READ-ONLY</span>\n  </div>\n  <nav>\n    <a class="active" href="/systems">SYSTEMS</a>\n    <a href="/world">WORLD</a>\n    <span class="future">HOUSE</span>\n    <span class="future">SENSORS</span>\n    <span class="future">SYSTEM / AI</span>\n  </nav>\n</header>\n\n<section class="status-strip">\n  <div class="status"><div class="label">CIC HEALTH</div><div id="s-health" class="value unknown">--</div></div>\n  <div class="status"><div class="label">OBSERVATION</div><div id="s-obs" class="value unknown">--</div></div>\n  <div class="status"><div class="label">WLAN</div><div id="s-wlan" class="value unknown">--</div></div>\n  <div class="status"><div class="label">API</div><div id="s-api" class="value unknown">CONNECTING</div></div>\n</section>\n\n<main>\n  <div class="grid">\n    <section class="card">\n      <h2>ENGAGE ONE // HOST</h2>\n      <div class="metrics">\n        <div class="metric"><span class="label">CPU</span><span id="cpu" class="v">--</span><span id="load" class="sub">--</span></div>\n        <div class="metric"><span class="label">MEMORY</span><span id="mem" class="v">--</span><span id="memsub" class="sub">--</span></div>\n        <div class="metric"><span class="label">STORAGE</span><span id="disk" class="v">--</span><span id="disksub" class="sub">--</span></div>\n        <div class="metric"><span class="label">TEMPERATURE</span><span id="temp" class="v">--</span><span id="tempsub" class="sub">--</span></div>\n        <div class="metric"><span class="label">UPTIME</span><span id="uptime" class="v">--</span><span class="sub">host uptime</span></div>\n        <div class="metric"><span class="label">OBSERVATION</span><span id="hostobs" class="v">--</span><span id="hostfresh" class="sub">--</span></div>\n      </div>\n      <div id="hostreason" class="reason" hidden></div>\n    </section>\n\n    <section class="card">\n      <h2>TENDA U11 PRO // WLAN PROVIDER</h2>\n      <div class="metrics">\n        <div class="metric"><span class="label">LINK</span><span id="link" class="v">--</span><span id="ssid" class="sub">--</span></div>\n        <div class="metric"><span class="label">SIGNAL</span><span id="signal" class="v">--</span><span id="band" class="sub">--</span></div>\n        <div class="metric"><span class="label">RX</span><span id="rx" class="v">--</span><span class="sub">Mbps</span></div>\n        <div class="metric"><span class="label">TX</span><span id="tx" class="v">--</span><span class="sub">Mbps</span></div>\n        <div class="metric"><span class="label">USB</span><span id="usb" class="v">--</span><span id="usbsub" class="sub">--</span></div>\n        <div class="metric"><span class="label">IPv4</span><span id="ipv4" class="v">--</span><span id="tendafresh" class="sub">--</span></div>\n      </div>\n      <div id="tendareason" class="reason" hidden></div>\n    </section>\n  </div>\n</main>\n\n<div class="foot">\n  Projection only. Browser performs no hardware, kernel, NetworkManager, or actuator queries.\n  <span id="generated"></span>\n</div>\n\n<script>\nconst $ = (id) => document.getElementById(id);\nconst cls = (el, value) => {\n  el.className = "value " + String(value || "unknown").toLowerCase();\n};\nconst pct = (v) => Number.isFinite(v) ? v.toFixed(1) + "%" : "--";\nconst num = (v, digits=1) => Number.isFinite(v) ? v.toFixed(digits) : "--";\nconst gib = (v) => Number.isFinite(v) ? (v / 1073741824).toFixed(1) + " GiB" : "--";\nconst uptime = (s) => {\n  if (!Number.isFinite(s)) return "--";\n  const d = Math.floor(s / 86400);\n  const h = Math.floor((s % 86400) / 3600);\n  const m = Math.floor((s % 3600) / 60);\n  return d ? `${d}d ${h}h ${m}m` : `${h}h ${m}m`;\n};\nconst reasons = (el, health, obs) => {\n  const values = [...(health?.reasons || []), ...(obs?.reasons || [])];\n  el.hidden = values.length === 0;\n  el.textContent = values.join(" // ");\n};\nasync function refresh() {\n  try {\n    const response = await fetch("/api/v1/systems", {cache: "no-store"});\n    if (!response.ok) throw new Error("HTTP " + response.status);\n    const d = await response.json();\n\n    $("s-api").textContent = "LIVE";\n    cls($("s-api"), "current");\n\n    $("s-health").textContent = String(d.summary.health).toUpperCase();\n    cls($("s-health"), d.summary.health);\n\n    $("s-obs").textContent = String(d.summary.observation).toUpperCase();\n    cls($("s-obs"), d.summary.observation);\n\n    $("s-wlan").textContent = d.summary.wlan_connected ? "CONNECTED" : "DISCONNECTED";\n    cls($("s-wlan"), d.summary.wlan_connected ? "connected" : "disconnected");\n\n    const h = d.host;\n    $("cpu").textContent = pct(h.compute.cpu_percent);\n    $("load").textContent = `load ${num(h.compute.load_1m, 2)} // ${h.compute.logical_cpus ?? "--"} logical CPUs`;\n    $("mem").textContent = pct(h.memory.used_percent);\n    $("memsub").textContent = `${gib(h.memory.available_bytes)} available`;\n    $("disk").textContent = pct(h.storage.used_percent);\n    $("disksub").textContent = `${gib(h.storage.free_bytes)} free`;\n    $("temp").textContent = Number.isFinite(h.temperature.celsius) ? num(h.temperature.celsius) + " °C" : "--";\n    $("tempsub").textContent = h.temperature.source || "--";\n    $("uptime").textContent = uptime(h.uptime.uptime_seconds);\n    $("hostobs").textContent = String(h.observation.availability).toUpperCase();\n    $("hostfresh").textContent = `${num(h.observation.freshness_seconds, 1)} s since observation`;\n    reasons($("hostreason"), h.health, h.observation);\n\n    const t = d.tenda;\n    $("link").textContent = t.wifi.connected ? "CONNECTED" : "DISCONNECTED";\n    $("link").className = "v " + (t.wifi.connected ? "connected" : "disconnected");\n    $("ssid").textContent = t.wifi.ssid || "--";\n    $("signal").textContent = Number.isFinite(t.wifi.signal_dbm) ? `${t.wifi.signal_dbm} dBm` : "--";\n    $("band").textContent = [t.wifi.band, Number.isFinite(t.wifi.frequency_mhz) ? `${t.wifi.frequency_mhz} MHz` : null].filter(Boolean).join(" // ") || "--";\n    $("rx").textContent = num(t.wifi.rx_mbps);\n    $("tx").textContent = num(t.wifi.tx_mbps);\n    $("usb").textContent = t.usb.present ? "PRESENT" : "ABSENT";\n    $("usbsub").textContent = [t.usb.usb_id, t.usb.mode].filter(Boolean).join(" // ") || "--";\n    $("ipv4").textContent = t.wifi.ipv4 || "--";\n    $("tendafresh").textContent = `${num(t.observation.freshness_seconds, 1)} s since observation`;\n    reasons($("tendareason"), t.health, t.observation);\n\n    $("generated").textContent = " // served " + d.presentation.generated_at;\n  } catch (error) {\n    $("s-api").textContent = "UNAVAILABLE";\n    cls($("s-api"), "unavailable");\n    $("generated").textContent = " // " + error;\n  }\n}\nrefresh();\nsetInterval(refresh, 2000);\n</script>\n</body>\n</html>\n'

WORLD_HTML = '<!doctype html>\n<html lang="en">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width, initial-scale=1">\n<title>Personal CIC // World</title>\n<style>\n:root { color-scheme: dark; --bg:#080c10; --panel:#0f151b; --panel2:#121b22; --line:#25323d; --text:#e7edf2; --muted:#8da0af; --good:#74d99f; --warn:#e8c56d; --bad:#ef7e7e; --unknown:#9aa7b2; --accent:#79b8ff; }\n* { box-sizing:border-box; }\nbody { margin:0; background:var(--bg); color:var(--text); font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace; }\nheader { position:sticky; top:0; z-index:10; background:rgba(8,12,16,.96); border-bottom:1px solid var(--line); }\n.brand { display:flex; align-items:baseline; gap:14px; padding:16px 20px 10px; }\n.brand h1 { margin:0; font-size:18px; letter-spacing:.12em; }\n.readonly { color:var(--accent); border:1px solid #2d5f8a; border-radius:999px; padding:2px 8px; font-size:10px; letter-spacing:.08em; }\nnav { display:flex; gap:8px; padding:0 20px 12px; overflow-x:auto; }\nnav span, nav a { color:var(--muted); border:1px solid var(--line); padding:6px 9px; border-radius:4px; white-space:nowrap; font-size:11px; }\nnav a { text-decoration:none; }\nnav .active { color:var(--text); border-color:#466174; background:#111b23; }\nnav .future { opacity:.45; }\n.status-strip { display:grid; grid-template-columns:repeat(4,minmax(0,1fr)); gap:8px; padding:12px 20px 0; }\n.status,.card { background:var(--panel); border:1px solid var(--line); border-radius:7px; }\n.status { padding:10px 12px; }\n.label { color:var(--muted); font-size:10px; letter-spacing:.1em; }\n.value { font-size:14px; margin-top:4px; }\n.current,.nominal,.connected { color:var(--good); } .degraded,.warning { color:var(--warn); } .unavailable,.critical { color:var(--bad); } .unknown { color:var(--unknown); }\nmain { padding:14px 20px 28px; }\n.grid { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:12px; }\n.card { overflow:hidden; }\n.card h2 { margin:0; padding:12px 14px; font-size:12px; letter-spacing:.08em; border-bottom:1px solid var(--line); background:var(--panel2); }\n.metrics { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); }\n.metric { min-height:76px; padding:12px 14px; border-right:1px solid var(--line); border-bottom:1px solid var(--line); }\n.metric:nth-child(even) { border-right:0; }\n.metric .v { display:block; margin-top:5px; font-size:17px; overflow-wrap:anywhere; }\n.metric .sub { color:var(--muted); display:block; margin-top:4px; font-size:10px; line-height:1.45; }\n.alerts { padding:12px 14px; }\n.alert { border-top:1px solid var(--line); padding:10px 0; }\n.alert:first-child { border-top:0; }\n.alert .sev { font-size:10px; color:var(--warn); letter-spacing:.08em; }\n.alert .headline { margin-top:4px; font-size:12px; line-height:1.4; }\n.reason { padding:10px 14px; border-top:1px solid var(--line); color:var(--warn); font-size:11px; }\n.foot { color:var(--muted); padding:12px 20px 24px; font-size:10px; }\n@media (max-width:760px) { .status-strip{grid-template-columns:repeat(2,minmax(0,1fr));}.grid{grid-template-columns:1fr;} }\n</style>\n</head>\n<body>\n<header>\n<div class="brand"><h1>PERSONAL CIC // WORLD</h1><span class="readonly">READ-ONLY</span></div>\n<nav><a href="/systems">SYSTEMS</a><a class="active" href="/world">WORLD</a><span class="future">HOUSE</span><span class="future">SENSORS</span><span class="future">SYSTEM / AI</span></nav>\n</header>\n<section class="status-strip">\n<div class="status"><div class="label">LOCATION</div><div id="location" class="value">--</div></div>\n<div class="status"><div class="label">WEATHER SOURCE</div><div id="weather-source" class="value unknown">--</div></div>\n<div class="status"><div class="label">NWS ALERTS</div><div id="alerts-source" class="value unknown">--</div></div>\n<div class="status"><div class="label">API</div><div id="api" class="value unknown">CONNECTING</div></div>\n</section>\n<main><div class="grid">\n<section class="card"><h2>CURRENT WEATHER</h2><div class="metrics">\n<div class="metric"><span class="label">CONDITION</span><span id="condition" class="v">--</span><span id="provider-time" class="sub">--</span></div>\n<div class="metric"><span class="label">TEMPERATURE</span><span id="temp" class="v">--</span><span id="feels" class="sub">--</span></div>\n<div class="metric"><span class="label">HUMIDITY</span><span id="humidity" class="v">--</span><span id="clouds" class="sub">--</span></div>\n<div class="metric"><span class="label">WIND</span><span id="wind" class="v">--</span><span id="gust" class="sub">--</span></div>\n<div class="metric"><span class="label">PRECIPITATION</span><span id="precip" class="v">--</span><span class="sub">current model interval</span></div>\n<div class="metric"><span class="label">OBSERVATION</span><span id="weather-obs" class="v">--</span><span id="weather-fresh" class="sub">--</span></div>\n</div><div id="weather-reason" class="reason" hidden></div></section>\n<section class="card"><h2>LOCAL FORECAST</h2><div class="metrics">\n<div class="metric"><span class="label">DATE</span><span id="forecast-date" class="v">--</span><span class="sub">Open-Meteo daily forecast</span></div>\n<div class="metric"><span class="label">HIGH / LOW</span><span id="high-low" class="v">--</span><span class="sub">°F</span></div>\n<div class="metric"><span class="label">MAX PRECIP CHANCE</span><span id="precip-prob" class="v">--</span><span class="sub">daily maximum probability</span></div>\n<div class="metric"><span class="label">SUNRISE / SUNSET</span><span id="sun" class="v">--</span><span class="sub">provider local time</span></div>\n</div></section>\n<section class="card" style="grid-column:1/-1"><h2>NATIONAL WEATHER SERVICE // ACTIVE ALERTS</h2>\n<div class="metrics"><div class="metric"><span class="label">ACTIVE</span><span id="alert-count" class="v">--</span><span id="alert-authority" class="sub">--</span></div>\n<div class="metric"><span class="label">HIGHEST SEVERITY</span><span id="severity" class="v">--</span><span id="alerts-fresh" class="sub">--</span></div></div>\n<div id="alert-list" class="alerts"></div><div id="alerts-reason" class="reason" hidden></div></section>\n</div></main>\n<div class="foot">Remote provider reports are retained with retrieval freshness and provider timestamps. Provider failure does not fabricate new weather/alert values. Weather data: <a href="https://open-meteo.com/" target="_blank" rel="noopener noreferrer">Open-Meteo</a> (<a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener noreferrer">CC BY 4.0</a>). <span id="generated"></span></div>\n<script>\nconst $=id=>document.getElementById(id); const num=(v,d=1)=>Number.isFinite(v)?v.toFixed(d):"--";\nconst cls=(el,v)=>{el.className="value "+String(v||"unknown").toLowerCase();};\nconst reason=(el,obs)=>{const r=obs?.reasons||[];el.hidden=r.length===0;el.textContent=r.join(" // ");};\nasync function refresh(){try{const r=await fetch(\'/api/v1/world\',{cache:\'no-store\'});if(!r.ok)throw new Error(\'HTTP \'+r.status);const d=await r.json();\n$(\'api\').textContent=\'LIVE\';cls($(\'api\'),\'current\');$(\'location\').textContent=d.location.label||\'--\';\nconst w=d.weather,o=w.observation;$(\'weather-source\').textContent=String(o.availability).toUpperCase();cls($(\'weather-source\'),o.availability);\n$(\'condition\').textContent=w.condition||\'--\';$(\'provider-time\').textContent=w.provider_observed_at?`provider ${w.provider_observed_at}`:\'--\';\n$(\'temp\').textContent=Number.isFinite(w.temperature_f)?`${num(w.temperature_f)} °F`:\'--\';$(\'feels\').textContent=Number.isFinite(w.apparent_temperature_f)?`feels ${num(w.apparent_temperature_f)} °F`:\'--\';\n$(\'humidity\').textContent=Number.isFinite(w.relative_humidity_percent)?`${num(w.relative_humidity_percent,0)}%`:\'--\';$(\'clouds\').textContent=Number.isFinite(w.cloud_cover_percent)?`${num(w.cloud_cover_percent,0)}% cloud cover`:\'--\';\n$(\'wind\').textContent=Number.isFinite(w.wind_speed_mph)?`${num(w.wind_speed_mph)} mph`:\'--\';$(\'gust\').textContent=Number.isFinite(w.wind_gust_mph)?`gust ${num(w.wind_gust_mph)} mph // ${num(w.wind_direction_deg,0)}°`:\'--\';\n$(\'precip\').textContent=Number.isFinite(w.precipitation_in)?`${num(w.precipitation_in,2)} in`:\'--\';$(\'weather-obs\').textContent=String(o.availability).toUpperCase();$(\'weather-fresh\').textContent=Number.isFinite(o.freshness_seconds)?`${num(o.freshness_seconds,0)} s since retrieval`:\'--\';reason($(\'weather-reason\'),o);\nconst f=w.forecast||{};$(\'forecast-date\').textContent=f.forecast_date||\'--\';$(\'high-low\').textContent=(Number.isFinite(f.high_f)&&Number.isFinite(f.low_f))?`${num(f.high_f)} / ${num(f.low_f)}`:\'--\';$(\'precip-prob\').textContent=Number.isFinite(f.precipitation_probability_max_percent)?`${num(f.precipitation_probability_max_percent,0)}%`:\'--\';$(\'sun\').textContent=[f.sunrise,f.sunset].filter(Boolean).join(\' / \')||\'--\';\nconst a=d.alerts,ao=a.observation;$(\'alerts-source\').textContent=String(ao.availability).toUpperCase();cls($(\'alerts-source\'),ao.availability);$(\'alert-count\').textContent=Number.isFinite(a.active_count)?String(a.active_count):\'--\';$(\'alert-authority\').textContent=a.authoritative_now?\'current provider result\':\'LAST KNOWN — source not current\';$(\'severity\').textContent=a.highest_severity||\'NONE\';$(\'alerts-fresh\').textContent=Number.isFinite(ao.freshness_seconds)?`${num(ao.freshness_seconds,0)} s since retrieval`:\'--\';reason($(\'alerts-reason\'),ao);\nconst list=$(\'alert-list\');list.innerHTML=\'\';const items=a.alerts||[];if(items.length===0){list.textContent=a.authoritative_now?\'No active NWS alerts for configured point.\':\'No current alert claim available.\';}else{for(const item of items){const div=document.createElement(\'div\');div.className=\'alert\';const sev=document.createElement(\'div\');sev.className=\'sev\';sev.textContent=`${item.severity||\'Unknown\'} // ${item.event||\'Alert\'}`;const h=document.createElement(\'div\');h.className=\'headline\';h.textContent=item.headline||item.event||\'Weather alert\';div.append(sev,h);list.append(div);}}\n$(\'generated\').textContent=\' // served \'+d.presentation.generated_at;\n}catch(e){$(\'api\').textContent=\'UNAVAILABLE\';cls($(\'api\'),\'unavailable\');$(\'generated\').textContent=\' // \'+e;}}\nrefresh();setInterval(refresh,5000);\n</script></body></html>'
